    "Biết ngày giờ hiện tại trên máy, đếm số ngày giữa hai mốc.": "知道本机当前的日期和时间，并能计算两个日期之间的天数。",
    "Buộc mô hình trả lời đúng lược đồ JSON bên dưới.": "强制模型严格按下面的 JSON 模式回复。",
    "Bài đo định vị: chỉ đúng {0}/10 nút trên ảnh chụp cửa sổ AIVN Bench (đo trên {1}).": "定位测试：在 AIVN Bench 窗口截图上只点对了 {0}/10 个按钮（在 {1} 上测得）。",
    "Bài đo: không gửi thật": "测量：不会真的发送",
    "Bán hàng": "销售",
    "Báo cáo": "报表",
    "Báo cáo này chưa có dữ liệu để xuất.": "此报表还没有可导出的数据。",
    "Báo cáo quý 3": "第三季度报告",
    "Báo giá": "报价",
    "Báo giá chưa có dòng sản phẩm nào có số lượng.": "报价单中没有数量大于零的产品行。",
    "Báo giá cần chọn khách hàng.": "报价单需要选择客户。",
    "Báo giá mới": "新报价单",
    "Báo giá {0} đã gửi cho khách": "报价单 {0} 已发送给客户",
