    "Báo giá đang mở": "未结报价单",
    "Báo giá đã gửi": "报价单已发送",
    "Báo giá:": "报价单：",
    "Bây giờ là mấy giờ, hôm nay thứ mấy? Còn bao nhiêu ngày nữa đến Tết Dương lịch?": "现在几点，今天星期几？离元旦还有多少天？",
    "Bây giờ:": "现在：",
    "Bước 1: Tải một mô hình": "第 1 步：下载模型",
    "Bước 2: Dùng AIVN AGENT": "第 2 步：使用 AIVN AGENT",
    "Bước 3: Phím tắt": "第 3 步：快捷键",
    "Bước lỗi": "失败的步骤",
    "Bạn": "你",
    "Bạn CHƯA yêu cầu thao tác này trong tin nhắn.": "你在消息中并没有要求此操作。",
    "Bạn có thể bỏ trong Cài đặt AIVN AGENT.": "你可以在 AIVN AGENT 设置中关闭它。",
    "Bạn cần tải một mô hình trước khi trò chuyện. Mở Khám phá để tải (gợi ý: Qwen3 4B Instruct 2507, hoặc Qwen3 8B nếu máy mạnh)?": "对话前需要先下载一个模型。打开“发现”去下载吗（推荐：Qwen3 4B Instruct 2507，电脑性能强可选 Qwen3 8B）？",
    "Bạn kiểm tra lại cửa sổ trò chuyện giúp mình, hoặc giao lại việc để mình làm lại từng bước": "请检查一下聊天窗口，或重新交代任务，让我一步步重做",
    "Bạn kiểm tra lại cửa sổ trò chuyện giúp mình, hoặc giao lại việc để mình làm lại từng bước.": "请检查一下聊天窗口，或重新交代任务，让我一步步重做。",
    "Bạn kiểm tra lại tên ứng dụng giúp mình (hoặc bấm \"Kiểm tra quét ứng dụng\" trong Cài đặt → Nâng cao để xem AIVN thấy những ứng dụng nào).": "请检查一下应用名称（或在 设置 → 高级 中点击“检查应用扫描”，查看 AIVN 找到了哪些应用）。",
    "Bạn là AIVN, một trợ lý AI thân thiện. Hãy trả lời bằng tiếng Việt, rõ ràng và chính xác.": "你是 AIVN，一个友好的 AI 助手。请用越南语清晰、准确地回答。",
    "Bạn là AIVN. Luôn trả lời bằng một đối tượng JSON đúng lược đồ được yêu cầu, nội dung bằng tiếng Việt.": "你是 AIVN。始终以符合所需模式的 JSON 对象回复，内容使用越南语。",
    "Bạn là AIVN. Trả lời bằng tiếng Việt, ngắn gọn và đúng trọng tâm. Dùng gạch đầu dòng khi liệt kê. Nếu không chắc chắn, hãy nói rõ là không chắc thay vì đoán.": "你是 AIVN。用越南语简洁、切题地回答。列举时使用项目符号。如果不确定，请明确说明，不要猜测。",
    "Bạn là biên dịch viên. Nếu văn bản là tiếng Việt, dịch sang tiếng Anh; nếu là ngôn ngữ khác, dịch sang tiếng Việt. Chỉ trả về bản dịch, giữ nguyên định dạng, tên riêng và thuật ngữ chuyên ngành.": "你是翻译。如果文本是越南语，译成英语；如果是其他语言，译成越南语。只返回译文，保留格式、专有名词和专业术语。",
    "Bạn là kỹ sư phần mềm giàu kinh nghiệm. Giải thích bằng tiếng Việt, mã nguồn đặt trong khối ``` có ghi tên ngôn ngữ. Ưu tiên lời giải đơn giản, chạy được, có xử lý lỗi; nêu giả định nếu đề bài chưa rõ.": "你是经验丰富的软件工程师。用越南语解释，代码放在标明语言名称的 ``` 代码块中。优先给出简单、可运行且有错误处理的方案；题目不明确时说明假设。",
    "Bạn là một cây bút tiếng Việt giàu hình ảnh. Viết tự nhiên, giàu cảm xúc, tránh sáo rỗng; giữ đúng giọng văn và độ dài người dùng yêu cầu.": "你是一位文笔生动的越南语作者。写作自然、富有感情，避免陈词滥调；保持用户要求的语气和篇幅。",
    "Bạn thêm": "你添加了",
    "Bạn thử giao lại việc, hoặc chia thành bước ngắn hơn; nếu máy đang bận nhiều, hãy chờ máy rảnh rồi thử lại.": "请重新交代任务或拆成更短的步骤；如果电脑很忙，请等空闲后再试。",
    "Bạn từ chối": "你已拒绝",
    "Bạn đang dùng bản mới nhất ({0}).": "你使用的是最新版本（{0}）。",
    "Bạn đang dùng bản mới nhất mà AIVN biết.": "你使用的是 AIVN 已知的最新版本。",
    "Bạn đang nhớ gì về tôi?": "你记得关于我的哪些事？",
    "Bản 4B luôn suy nghĩ trước khi trả lời: chậm hơn bản Instruct nhưng giỏi toán, logic và các bài nhiều bước.": "4B 版本总是先思考再回答：比 Instruct 版慢，但擅长数学、逻辑和多步骤问题。",
    "Bản MoE của Granite 4.0: tổng 7B, mỗi token dùng khoảng 1B nên nhanh trên CPU.": "Granite 4.0 的 MoE 版本：总计 7B，每个 token 只用约 1B，因此在 CPU 上很快。",
    "Bản Qwen3 4B trả lời trực tiếp (không thinking), nhanh và chất lượng cao.": "直接回答（不思考）的 Qwen3 4B，速度快、质量高。",
    "Bản lớn của InternVL3: hiểu ảnh, biểu đồ, giấy tờ chi tiết hơn.": "InternVL3 大版本：更细致地理解图片、图表和文档。",
    "Bản lớn hơn của Gemma 3n, trả lời tốt hơn E2B. Trong AIVN chỉ dùng phần chữ.": "Gemma 3n 的较大版本，回答优于 E2B。AIVN 只使用文字部分。",
    "Bản lớn hơn của Qwen3-VL: hiểu giao diện và làm nhiều bước chắc chắn hơn.": "Qwen3-VL 的较大版本：更好地理解界面，多步骤任务更可靠。",
    "Bản mã hoá của khoá riêng trên máy này sẽ bị xoá. Hãy chắc chắn bạn còn giữ tệp aivn-admin-key.json ở nơi an toàn.": "本机上加密的私钥将被删除。请确认你仍把 aivn-admin-key.json 保存在安全的地方。",
    "Bản phù hợp nhất còn chạy được trên máy này": "本机仍可运行的最合适版本",
    "Bản đi kèm (Vulkan / Metal / CPU)": "随附版本（Vulkan / Metal / CPU）",
    "Bảng mọi bản lượng tử (Q4/Q5/Q6/Q8…) của repo này, mỗi dòng có mức chạy trên máy bạn": "此仓库所有量化版本（Q4/Q5/Q6/Q8……）的表格，每行显示在你电脑上的运行情况",
    "Bảng phím tắt này": "本快捷键表",
    "Bảo mật & Quản trị": "安全与管理",
    "Bấm": "点击",
    "Bấm chuột phải": "右键点击",
    "Bấm nút có tên": "点击有名称的按钮",
    "Bấm phím": "按键",
    "Bấm vào nút Bắt đầu (Start) trên thanh tác vụ": "点击任务栏上的“开始”按钮",
    "Bấm vào đúng ô nhập rồi gõ lại. Đừng gõ vào nút hay vào ô đã có sẵn chữ.": "请点进正确的输入框再重新输入。不要输入到按钮上，也不要输入到已有文字的框里。",
    "Bấm đúp": "双击",
    "Bấm để bật.": "点击开启。",
    "Bấm để tắt.": "点击关闭。",
    "Bấm “Kiểm tra cập nhật” để xem có bản mới không.": "点击“检查更新”查看是否有新版本。",
    "Bấm “Tìm kiếm” không đổi màn hình → dùng phím tắt {0} của {1}": "点击“搜索”屏幕没有变化 → 使用 {1} 的快捷键 {0}",
    "Bật": "开启",
    "Bật Khoá ứng dụng": "开启应用锁",
    "Bật công cụ này": "启用此工具",
    "Bật Điều khiển máy tính (thử nghiệm)?": "开启电脑控制（实验性）？",
    "Bật “Tự làm không hỏi”?": "开启“自动执行不询问”？",
    "Bật: AIVN AGENT tự làm các bước thường mà không hỏi. Vẫn hỏi khi gửi nội dung khác lời bạn, xoá, thanh toán, chạy lệnh.": "开启：AIVN AGENT 执行普通步骤时不再询问。发送与你原话不同的内容、删除、付款、运行命令时仍会询问。",
