    "Bộ máy nhìn ảnh và AIVN AGENT chạy bằng llama.cpp (llama-server). Bộ cài có sẵn bản Vulkan (Windows), Metal (Mac) hoặc CPU (Linux). Máy có GPU NVIDIA có thể tải thêm bản CUDA — trên một số GPU có thể nhanh hơn Vulkan (xem số đo bên dưới); nếu CUDA lỗi, AIVN tự quay về bản đi kèm. Mở nhanh: Ctrl+Shift+R.": "图像识别引擎和 AIVN AGENT 基于 llama.cpp（llama-server）运行。安装包自带 Vulkan（Windows）、Metal（Mac）或 CPU（Linux）版本。配备 NVIDIA GPU 的电脑可额外下载 CUDA 版本——在部分 GPU 上可能比 Vulkan 更快（见下方实测）；如果 CUDA 出错，AIVN 会自动退回随附版本。快捷键：Ctrl+Shift+R。",
