    "Chưa có hàng lưu kho.": "还没有库存商品。",
    "Chưa có hàng lưu kho. Thêm sản phẩm loại “Hàng lưu kho” ở Bán hàng → Sản phẩm.": "还没有库存商品。请在 销售 → 产品 中添加类型为“库存商品”的产品。",
    "Chưa có khách hàng nào. Bấm “＋ Liên hệ” hoặc “⬆ Nhập” từ tệp Excel/CSV.": "还没有客户。点击“＋ 联系人”或从 Excel/CSV 文件“⬆ 导入”。",
    "Chưa có lần kiểm kê nào. Bấm “Kiểm kê” ở Kho → Tồn kho.": "还没有盘点记录。在 库存 → 库存量 中点击“盘点”。",
    "Chưa có lịch nào. Tạo lời nhắc ở khung bên trái, hoặc nhờ AIVN AGENT: “nhắc tôi 9 giờ sáng mai nộp bài”.": "还没有日程。在左侧面板创建提醒，或让 AIVN AGENT 帮忙：“明天早上 9 点提醒我交作业”。",
