    "Chưa nạp mô hình nhìn ảnh — lần nạp tới sẽ dùng: {0}": "尚未加载图像识别模型——下次加载将使用：{0}",
    "Chưa nạp mô hình nào. Yêu cầu API ghi \"model\" là mô hình đã tải sẽ được tự nạp.": "未加载模型。若 API 请求中的 \"model\" 是已下载的模型，会自动加载。",
