    "Chưa thấy ứng dụng khớp \"{0}\". Hãy chụp màn hình này hoặc bấm Sao chép rồi gửi cho người hỗ trợ.": "没有找到与 \"{0}\" 匹配的应用。请截下此画面或点击“复制”，然后发给技术支持。",
    "Chưa tải. Dung lượng tải: {0} (sau khi giải nén khoảng 1,2 GB). Cần driver NVIDIA {1} trở lên.": "尚未下载。下载大小：{0}（解压后约 1.2 GB）。需要 NVIDIA 驱动 {1} 或更高版本。",
