    "Chạy chậm trên máy này (~{0} token/giây{1}): AIVN AGENT vẫn làm được nhưng mỗi bước có thể mất 10–30 giây.": "在本机运行较慢（约 {0} token/秒{1}）：AIVN AGENT 仍可使用，但每一步可能需要 10–30 秒。",
    "Chạy lệnh": "运行命令",
