    "Chạy mã Python 3 có trên máy trong thư mục tạm, chặn mạng, tối đa 10 giây.": "在临时文件夹中运行本机安装的 Python 3 代码，禁止联网，最长 10 秒。",
    "Chạy mô hình AI ngay trên máy tính của bạn, riêng tư và không cần Internet.": "在你的电脑上直接运行 AI 模型——私密，无需联网。",
    "Chạy mượt": "运行流畅",
    "Chạy mượt trên máy này": "在本机运行流畅",
    "Chạy nền": "后台运行",
    "Chạy trên các mô hình Qwen3-VL 2B/4B/8B đã tải: gọi công cụ, định vị nút, việc trong ứng dụng GIẢ (Messenger/Zalo/Outlook “AIVN Bench”), âm lượng (giả lập) và mở ứng dụng. Mất khoảng 20–40 phút; đừng dùng chuột/bàn phím trong lúc đo. Không gửi tin nhắn hay thư thật nào. Xong sẽ lưu MỘT tệp .json trong thư mục Tải về.": "在已下载的 Qwen3-VL 2B/4B/8B 模型上运行：工具调用、按钮定位、在“假”应用（Messenger/Zalo/Outlook “AIVN Bench”）中的任务、音量（模拟）和打开应用。大约需要 20–40 分钟；测试期间请勿使用鼠标/键盘。不会发送任何真实消息或邮件。完成后会在“下载”文件夹中保存一个 .json 文件。",
    "Chạy với mô hình đang nạp (hoặc mô hình dùng gần nhất). Không thể xoá/ghi đè tệp vì không có ai xác nhận.": "使用已加载的模型（或最近使用的模型）运行。由于无人确认，无法删除/覆盖文件。",
    "Chạy đoạn mã JavaScript trong hộp cát cách ly (không mạng, không tệp) để tính toán, xử lý văn bản.": "在隔离的沙箱中运行 JavaScript（无网络、无文件），用于计算和文本处理。",
    "Chạy đoạn mã này?": "运行这段代码？",
    "Chất lượng cao nhất còn nằm trọn VRAM trên máy này": "本机显存可完全容纳的最高质量版本",
    "Chất lượng cao, cần máy mạnh (từ 16 GB RAM). Chưa hỗ trợ đầu vào ảnh.": "质量高，需要高性能电脑（16 GB 以上内存）。暂不支持图片输入。",
    "Chế độ": "模式",
    "Chế độ hiệu năng mới áp dụng đầy đủ khi nạp lại mô hình.": "新的性能模式在重新加载模型后才会完全生效。",
    "Chỉ CPU": "仅 CPU",
    "Chỉ CPU (đã tắt GPU)": "仅 CPU（已关闭 GPU）",
    "Chỉ cho máy yếu không có mô hình nào chạy mượt: mô hình lớn hơn VRAM nhiều lần (ví dụ Qwen3-VL 8B trên GPU 4 GB) hiện trong bộ chọn với nhãn “Rất chậm”. Mỗi bước có thể mất 1–3 phút; không bao giờ là lựa chọn gợi ý.": "仅适用于没有模型能流畅运行的低配电脑：比显存大很多的模型（例如 4 GB GPU 上的 Qwen3-VL 8B）会以“非常慢”标签出现在选择器中。每一步可能需要 1–3 分钟；永远不会是推荐选项。",
    "Chỉ chọn trong K từ (token) có xác suất cao nhất. 0 = tắt.": "只从概率最高的 K 个词元中选择。0 = 关闭。",
    "Chỉ có trên Windows 64-bit — máy này dùng bản đi kèm (Metal trên Mac, Vulkan/CPU trên Linux).": "仅适用于 64 位 Windows——本机使用内置版本（Mac 上为 Metal，Linux 上为 Vulkan/CPU）。",
    "Chỉ cần cho mô hình": "仅模型需要",
    "Chỉ dành cho máy yếu (vd. laptop GPU 4 GB) khi mô hình nhỏ chưa làm tốt việc của bạn. Mô hình lớn (vd. Qwen3-VL 8B) sẽ tràn sang RAM: mỗi bước có thể mất 1–3 phút, máy nóng và ồn hơn, ứng dụng khác chậm lại. AIVN AGENT chờ lâu gấp 3 lần trước khi báo hết giờ. Mô hình này không bao giờ được gợi ý ⭐ hay tự nạp — bạn phải tự chọn trong bộ chọn mô hình.": "仅适用于低配电脑（例如 4 GB GPU 的笔记本），且小模型无法很好地完成你的任务时。大模型（例如 Qwen3-VL 8B）会溢出到内存：每一步可能需要 1–3 分钟，电脑会更热、更吵，其他应用也会变慢。AIVN AGENT 会等待 3 倍的时间才报告超时。此模型永远不会被推荐 ⭐ 或自动加载——你必须在模型选择器中自己选择。",
    "Chỉ dùng CPU: tắt “Tăng tốc bằng GPU” ở thẻ Phần cứng & bộ máy. Trò chuyện chữ (không ảnh) luôn dùng bộ máy node-llama-cpp đi kèm.": "仅用 CPU：在“硬件与引擎”标签中关闭“GPU 加速”。纯文字聊天（无图片）始终使用随附的 node-llama-cpp 引擎。",
