    "Lưu ý trung thực: mã nguồn AIVN công khai trên GitHub, nên người rành kỹ thuật có thể tự sửa và build lại để bỏ bước kích hoạt. Cơ chế này giúp chủ sở hữu kiểm soát ai dùng bản AIVN chính thức, không phải biện pháp chống bẻ khoá tuyệt đối.": "坦白说明：AIVN 的源代码在 GitHub 上公开，懂技术的人可以自行修改并重新构建以跳过激活。此机制帮助所有者控制谁使用官方 AIVN 版本，并非绝对的防破解措施。",
    "Lược đồ JSON": "JSON 模式",
