    "Lượt này mô hình chưa thực sự thao tác gì — chưa có việc nào được làm. Bạn thử giao lại việc, nói rõ ứng dụng hay cửa sổ cần dùng.": "本轮模型并没有真正执行任何操作——什么都没完成。请重新交代任务，并说明要使用的应用或窗口。",
    "Lượt này đã dài quá giới hạn của AIVN AGENT nên được dừng lại. Hãy chia việc thành các bước nhỏ hơn.": "本轮超出了 AIVN AGENT 的上限，已停止。请把任务拆成更小的步骤。",
