    "Mô hình": "模型",
    "Mô hình 3B tinh chỉnh riêng cho tiếng Việt (Arcee AI, nền Qwen2.5).": "专门针对越南语微调的 3B 模型（Arcee AI，基于 Qwen2.5）。",
    "Mô hình 3–4 tỉ tham số (Q4_K_M) là cân bằng tốt giữa tốc độ và chất lượng.": "3–4B 参数模型（Q4_K_M）在速度和质量之间取得了很好的平衡。",
    "Mô hình 7B kinh điển của Mistral AI, mạnh với tiếng Anh và châu Âu.": "Mistral AI 的经典 7B 模型，擅长英语和欧洲语言。",
    "Mô hình 8B phổ biến, cân bằng giữa chất lượng và tốc độ.": "流行的 8B 模型，兼顾质量与速度。",
    "Mô hình GGUF": "GGUF 模型",
    "Mô hình GGUF phổ biến trên Hugging Face": "Hugging Face 上热门的 GGUF 模型",
    "Mô hình KHÔNG gọi công cụ trong lần thử: AIVN AGENT có thể không làm được việc.": "测试中模型没有调用工具：AIVN AGENT 可能无法完成任务。",
    "Mô hình MoE chuyên điều khiển máy tính, mạnh nhất nhóm Holo dùng được: VRAM không đủ thì chuyên gia MoE tự chia sang CPU, phần nhìn ảnh vẫn ở GPU; mỗi bước chậm hơn bản 9B. Chờ đo.": "专用于操控电脑的 MoE 模型，可用 Holo 模型中最强：显存不足时 MoE 专家自动拆分到 CPU，视觉部分仍在 GPU；每一步比 9B 版本慢。待测试。",
    "Mô hình MoE lớn hơn VRAM: để chuyên gia của N lớp đầu chạy trên CPU (phần nhìn ảnh vẫn ở GPU). Để trống: tự chia cho vừa VRAM.": "MoE 模型大于显存：让前 N 层的专家在 CPU 上运行（视觉部分仍在 GPU 上）。留空：自动拆分以适配显存。",
    "Mô hình MoE: tổng 30B tham số nhưng mỗi token chỉ dùng khoảng 3B, nên chạy nhanh hơn nhiều so với cỡ. Tệp 18,6 GB, cần 24 GB RAM trở lên.": "MoE 模型：总计 30B 参数，但每个 token 只用约 3B，因此运行速度远快于同等体积的模型。文件 18.6 GB，需要 24 GB 以上内存。",
    "Mô hình bắt đầu lặp lại cùng một câu nên AIVN đã tự dừng lại. Mẹo: chọn mô hình được đánh dấu dùng được cho AIVN AGENT, và nạp ít mô hình cùng lúc nếu GPU ít bộ nhớ.": "模型开始重复同一句话，AIVN 已自动停止。提示：选择标记为可用于 AIVN AGENT 的模型；如果 GPU 显存较少，请同时少加载几个模型。",
    "Mô hình chuyên tìm phần tử giao diện (dựa trên Qwen2.5-VL). Nhỏ, gọi công cụ qua giao thức văn bản.": "专门查找界面元素的模型（基于 Qwen2.5-VL）。体积小，通过文本协议调用工具。",
    "Mô hình chuyên tìm vị trí nút, ô, mục trên ảnh chụp màn hình (dựa trên Qwen2.5-VL 7B). Dùng làm “mắt nhìn” cho cặp điều khiển máy.": "专门在截图上定位按钮、输入框和项目的模型（基于 Qwen2.5-VL 7B）。用作电脑控制组合的“眼睛”。",
    "Mô hình chuyên điều khiển máy tính (web, ứng dụng, điện thoại) dựa trên Qwen3.5 4B, gọi công cụ sẵn. Chờ đo.": "基于 Qwen3.5 4B、专用于操控电脑（网页、应用、手机）的模型，原生支持工具调用。待测试。",
    "Mô hình chuyên điều khiển máy tính dựa trên Qwen3.5 9B, gọi công cụ sẵn. Chờ đo.": "基于 Qwen3.5 9B、专用于操控电脑的模型，原生支持工具调用。待测试。",
    "Mô hình chưa thao tác được trên máy tính trong lượt này (các bước khác đã chạy xong ở trên).": "本轮模型未能在电脑上执行操作（上面的其他步骤已完成）。",
