    "Mô hình doanh nghiệp của IBM, kiến trúc lai (Mamba + Transformer) tốn ít bộ nhớ khi hội thoại dài.": "IBM 的企业级模型，采用混合架构（Mamba + Transformer），长对话时占用内存少。",
    "Mô hình dừng ngay khi viết ra một trong các chuỗi này.": "模型一旦输出这些字符串之一就会停止。",
