    "Mô hình lớn của Mistral, nhìn được ảnh và gọi hàm. Cần máy mạnh (tệp 14,3 GB + 0,9 GB thị giác).": "Mistral 的大模型，可识图并调用函数。需要高性能电脑（文件 14.3 GB + 视觉 0.9 GB）。",
    "Mô hình mở của OpenAI (MoE), suy luận mạnh. Cần từ 16 GB RAM.": "OpenAI 的开放模型（MoE），推理能力强。需要 16 GB 以上内存。",
    "Mô hình mở hoàn toàn của Hugging Face (công bố cả dữ liệu huấn luyện), có chế độ suy nghĩ.": "Hugging Face 的完全开放模型（连训练数据也已公开），带思考模式。",
