    "Mở ứng dụng {0}.": "打开 {0} 应用。",
    "Mở ứng dụng, tệp, thư mục, trang web; xem/đóng ứng dụng; chạy lệnh (luôn hỏi bạn trước).": "打开应用、文件、文件夹、网页；查看/关闭应用；运行命令（总会先询问你）。",
    "Mở ứng dụng, tệp, thư mục, trang web; xem/đóng ứng dụng; chạy lệnh terminal; khoá màn hình, âm lượng… Chạy lệnh, đóng ứng dụng, tắt máy luôn hỏi bạn trước. Lệnh nguy hiểm (xoá hàng loạt, định dạng ổ đĩa, tải mã về chạy, quyền quản trị) bị chặn.": "打开应用、文件、文件夹、网页；查看/关闭应用；运行终端命令；锁屏、音量……运行命令、关闭应用、关机总会先询问你。危险命令（批量删除、格式化磁盘、下载并运行代码、管理员权限）会被阻止。",
    "Mục cài đặt": "设置分区",
