    "Mức chạy ở mục này tính với ngữ cảnh AIVN AGENT {0} token.": "此处的运行情况按 AIVN AGENT 上下文 {0} 个词元计算。",
    "Mức chạy ở mục này tính với ngữ cảnh AIVN AGENT {0} token: máy này không có mô hình AIVN AGENT nào nằm trọn VRAM ở 16K, nên AIVN dùng 12K (lịch sử và ảnh màn hình được tự thu gọn).": "此处的运行情况按 AIVN AGENT 上下文 {0} 个词元计算：本机没有任何 AIVN AGENT 模型能在 16K 下完全放入显存，因此 AIVN 使用 12K（历史记录和屏幕截图会自动压缩）。",
