    "Nhìn màn hình, chỉ đúng nút cần bấm (toạ độ 0-1000) và gọi công cụ gốc. Mức chạy trên máy bạn xem ở nhãn Chạy mượt/Chạy chậm.": "可查看屏幕，指出需要点击的按钮（0-1000 坐标）并原生调用工具。在“运行流畅/运行较慢”标签中查看其在你电脑上的运行情况。",
