    "Rất chậm trên máy này (~{0} token/giây{1}) — bạn đã tự bật. Mỗi bước có thể mất 1–3 phút, máy nóng và ồn hơn, các ứng dụng khác chậm lại; AIVN AGENT chờ lâu gấp {2} lần trước khi báo hết giờ. Không phải lựa chọn gợi ý.": "在本机上非常慢（约 {0} token/秒{1}）——由你手动开启。每一步可能需要 1–3 分钟，电脑会更热、更吵，其他应用会变慢；AIVN AGENT 会等待 {2} 倍的时间才报告超时。不是推荐选项。",
