    "Thế hệ sau Qwen3-VL 8B: nhìn màn hình và gọi công cụ tốt hơn theo số liệu nhà phát triển, tốn ít VRAM hơn. Chờ đo.": "Qwen3-VL 8B 的下一代：据开发者数据，看屏幕和调用工具更强，且占用显存更少。待测试。",
    "Thế hệ sau Qwen3-VL, nhìn ảnh sẵn, bộ đệm ngữ cảnh rất nhỏ nên nhẹ máy. Chờ đo: dùng cho AIVN AGENT sau khi đạt Bộ đo trên máy bạn.": "Qwen3-VL 的下一代，原生支持看图，上下文缓存很小，对电脑负担轻。待测试：在你的电脑上通过测试后即可用于 AIVN AGENT。",
