    "Trợ lý AI chạy hoàn toàn trên máy bạn — không gửi dữ liệu ra ngoài. Làm quen trong 30 giây nhé.": "完全在你的电脑上运行的 AI 助手 — 不会向外发送任何数据。用 30 秒熟悉一下吧。",
    "Trợ năng": "辅助功能",
    "Tuỳ chọn. Đo trên RTX 4070 SUPER với Qwen3-VL 8B: CUDA sinh chữ nhanh ngang Vulkan (86,0 so với 86,4 token/giây), đọc câu hỏi ngắn nhanh hơn một chút, ảnh lớn lúc nhanh lúc chậm hơn. Vì vậy AIVN mặc định dùng Vulkan đi kèm; chỉ tải CUDA nếu bạn muốn tự thử.": "可选。在 RTX 4070 SUPER 上用 Qwen3-VL 8B 实测：CUDA 生成速度与 Vulkan 相当（86.0 对 86.4 token/秒），读取短提示略快，处理大图时快时慢。因此 AIVN 默认使用内置的 Vulkan；只有想自己试试时才下载 CUDA。",
    "Tài liệu dài hơn giới hạn ngữ cảnh của mô hình, AIVN chỉ dùng một phần: {0}. Đã giữ phần mở đầu và các đoạn liên quan nhất tới câu hỏi. Tăng \"Độ dài ngữ cảnh\" trong hộp nạp mô hình (Ctrl+L) để dùng nhiều hơn.": "文档超出了模型的上下文上限，AIVN 只使用了其中一部分：{0}。已保留开头和与问题最相关的段落。在模型加载对话框（Ctrl+L）中增大“上下文长度”即可使用更多内容。",
