    "Tải Python 3 từ trang chính thức python.org (Windows: nhớ tích \"Add python.exe to PATH\" khi cài; macOS: cài gói .pkg). Cài xong, khởi động lại AIVN rồi bật nút Python.": "从官方网站 python.org 下载 Python 3（Windows：安装时记得勾选“Add python.exe to PATH”；macOS：安装 .pkg 包）。安装完成后，重新启动 AIVN 并打开 Python 开关。",
